import{_ as e,o as d,c as r,a2 as s}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse('{"title":"Protection Profiles","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/configuration/profiles.md","filePath":"openshield-xdp/configuration/profiles.md","lastUpdated":null}'),a={name:"openshield-xdp/configuration/profiles.md"};function o(n,t,i,l,h,p){return d(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="protection-profiles" tabindex="-1">Protection Profiles <a class="header-anchor" href="#protection-profiles" aria-label="Permalink to &quot;Protection Profiles&quot;">​</a></h1><p>OpenShield-XDP ships with <strong>70 pre-computed configurations</strong> across <strong>10 profiles × 7 intensity levels</strong>. Instead of tuning individual thresholds, you answer &quot;what do you host?&quot; and the installer picks the optimal preset.</p><h2 id="how-profiles-work" tabindex="-1">How profiles work <a class="header-anchor" href="#how-profiles-work" aria-label="Permalink to &quot;How profiles work&quot;">​</a></h2><p>Each profile encodes a <strong>protection philosophy</strong>:</p><ul><li><strong>Rate limits</strong> (PPS, BPS, TCP/UDP/ICMP/SYN thresholds) — how much traffic is allowed before scoring begins</li><li><strong>Scoring</strong> (violation scores, suspicion threshold, ban duration) — how aggressively traffic is metered and banned</li><li><strong>Detection features</strong> (entropy, TTL anomaly, packet size anomaly, SYN/FIN ratio, connection tracking) — which behavioral checks are active</li><li><strong>Escalation</strong> (auto subnet ban, panic circuit breaker) — how the system responds under sustained attack</li></ul><p>The 7 intensity levels (Strict → Low → Medium → Balanced → High → Very High → Extreme) scale every threshold by a multiplier. Balanced is always the recommended default.</p><h2 id="the-10-profiles" tabindex="-1">The 10 profiles <a class="header-anchor" href="#the-10-profiles" aria-label="Permalink to &quot;The 10 profiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Profile</th><th>Designed for</th></tr></thead><tbody><tr><td>1</td><td><strong>Ultra Strict</strong></td><td>Personal websites, admin panels, internal dashboards, login portals, small APIs, low-traffic applications</td></tr><tr><td>2</td><td><strong>Strict</strong></td><td>Blogs, portfolio sites, WordPress, company websites, small stores</td></tr><tr><td>3</td><td><strong>Balanced</strong> (default)</td><td>SaaS, APIs, ecommerce, communities, forums, general web hosting</td></tr><tr><td>4</td><td><strong>Performance</strong></td><td>Large APIs, streaming, downloads, reverse proxies, large websites</td></tr><tr><td>5</td><td><strong>Hosting</strong></td><td>Docker hosts, VPS nodes, shared hosting, Pterodactyl panels, Kubernetes</td></tr><tr><td>6</td><td><strong>Gaming</strong></td><td>Minecraft, FiveM, Rust, CS2, Terraria, voice servers, game hosting</td></tr><tr><td>7</td><td><strong>Enterprise</strong></td><td>Banks, government, large SaaS, critical infrastructure</td></tr><tr><td>8</td><td><strong>CDN / Edge</strong></td><td>CDN, reverse proxies, ISPs, large hosting providers, very high bandwidth</td></tr><tr><td>9</td><td><strong>Database / Storage</strong></td><td>Database servers, file storage, backups, mail servers</td></tr><tr><td>10</td><td><strong>Custom</strong></td><td>Mixed workloads, manual per-threshold tuning</td></tr></tbody></table><h2 id="the-7-intensity-levels" tabindex="-1">The 7 intensity levels <a class="header-anchor" href="#the-7-intensity-levels" aria-label="Permalink to &quot;The 7 intensity levels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Rate Multiplier</th><th>Effect</th></tr></thead><tbody><tr><td>Strict</td><td>0.40×</td><td>Most aggressive — fastest bans, tightest thresholds</td></tr><tr><td>Low</td><td>0.60×</td><td>Aggressive — slightly relaxed</td></tr><tr><td>Medium</td><td>0.80×</td><td>Moderately aggressive</td></tr><tr><td><strong>Balanced</strong></td><td><strong>1.00×</strong></td><td><strong>Recommended default</strong></td></tr><tr><td>High</td><td>1.35×</td><td>Relaxed — allows more legitimate traffic</td></tr><tr><td>Very High</td><td>1.75×</td><td>Very relaxed — minimal false positives</td></tr><tr><td>Extreme</td><td>3.00×</td><td>Most permissive — blocks only extreme abuse</td></tr></tbody></table><h2 id="per-profile-threshold-examples" tabindex="-1">Per-profile threshold examples <a class="header-anchor" href="#per-profile-threshold-examples" aria-label="Permalink to &quot;Per-profile threshold examples&quot;">​</a></h2><h3 id="syn-packets-per-second-syn-pps-threshold" tabindex="-1">SYN packets per second (<code>syn_pps_threshold</code>) <a class="header-anchor" href="#syn-packets-per-second-syn-pps-threshold" aria-label="Permalink to &quot;SYN packets per second (`syn_pps_threshold`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Profile</th><th>Strict (×0.40)</th><th>Balanced (×1.00)</th><th>Extreme (×3.00)</th></tr></thead><tbody><tr><td>Ultra Strict</td><td>28</td><td>70</td><td>210</td></tr><tr><td>Strict</td><td>44</td><td>110</td><td>330</td></tr><tr><td>Balanced</td><td>68</td><td>170</td><td>510</td></tr><tr><td>Performance</td><td>160</td><td>400</td><td>1,200</td></tr><tr><td>Hosting</td><td>400</td><td>1,000</td><td>3,000</td></tr><tr><td>Gaming</td><td>200</td><td>500</td><td>1,500</td></tr><tr><td>Enterprise</td><td>100</td><td>250</td><td>750</td></tr><tr><td>CDN / Edge</td><td>800</td><td>2,000</td><td>6,000</td></tr><tr><td>Database</td><td>60</td><td>150</td><td>450</td></tr></tbody></table><h3 id="packets-per-second-pps-threshold" tabindex="-1">Packets per second (<code>pps_threshold</code>) <a class="header-anchor" href="#packets-per-second-pps-threshold" aria-label="Permalink to &quot;Packets per second (`pps_threshold`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Profile</th><th>Strict (×0.40)</th><th>Balanced (×1.00)</th><th>Extreme (×3.00)</th></tr></thead><tbody><tr><td>Ultra Strict</td><td>160</td><td>400</td><td>1,200</td></tr><tr><td>Strict</td><td>200</td><td>500</td><td>1,500</td></tr><tr><td>Balanced</td><td>340</td><td>850</td><td>2,550</td></tr><tr><td>Performance</td><td>800</td><td>2,000</td><td>6,000</td></tr><tr><td>Hosting</td><td>2,000</td><td>5,000</td><td>15,000</td></tr><tr><td>Gaming</td><td>800</td><td>2,000</td><td>6,000</td></tr><tr><td>Enterprise</td><td>480</td><td>1,200</td><td>3,600</td></tr><tr><td>CDN / Edge</td><td>3,200</td><td>8,000</td><td>24,000</td></tr></tbody></table><p>Each of the <strong>34 tuned thresholds</strong> follows the same pattern — base value from the profile category, scaled by the intensity level, clamped to a safe range.</p><h2 id="workload-based-recommendation" tabindex="-1">Workload-based recommendation <a class="header-anchor" href="#workload-based-recommendation" aria-label="Permalink to &quot;Workload-based recommendation&quot;">​</a></h2><p>The installer presents 27 workload types. Select what you host, and the engine recommends the best profile:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Detected workloads: Minecraft Server, Docker Host, Pterodactyl Panel</span></span>\n<span class="line"><span>Recommended: Gaming Profile</span></span>\n<span class="line"><span>Reason: Tolerates legitimate UDP bursts while protecting against</span></span>\n<span class="line"><span>reflection and flood attacks. Allows modpacks, plugins, many</span></span>\n<span class="line"><span>concurrent game servers.</span></span></code></pre></div><p>See <a href="/pingless-studios-docs/openshield-xdp/getting-started/installation">Installation</a> for the interactive installer flow.</p>',20)])])}const m=e(a,[["render",o]]);export{g as __pageData,m as default};
